   378	            // 1. Policy owner with amount owed, within grace period
   379	            if (!hasGracePeriodOverdue()) {
   380	                return {
   381	                    status: PAYMENT_STATUS.POLICY_OWNER_WITH_AMOUNT_OWED,
   382	                    isError: true,
   383	                };
   384	            }
   385	
   386	            // 2. Policy owner with amount owed, overdue (past grace period)
   387	            if (hasGracePeriodOverdue()) {
   388	                return {
   389	                    isError: true,
   390	                    status: PAYMENT_STATUS.POLICY_OWNER_WITH_AMOUNT_OWED_OVERDUE,
   391	                };
   392	            }
   393	        } else {
   394	            // 3. Owner of policy under invoicing, within grace period
   395	            if (!hasGracePeriodOverdue()) {
   396	                return {
   397	                    status: PAYMENT_STATUS.OWNER_OF_POLICY_UNDER_INVOICING,
   398	                    isError: true,
   399	                };
   400	            }
   401	
   402	            // 4. Owner of policy under invoicing, overdue (past grace period)
   403	            if (hasGracePeriodOverdue()) {
   404	                return {
   405	                    status: PAYMENT_STATUS.OWNER_OF_POLICY_UNDER_INVOICING_OVERDUE,
   406	                    isError: true,
   407	                };
   408	            }
   409	        }
   410	    }
   411	    // 5. Billing disputed by cardholder
   412	    if (hasBillingDisputePending()) {
   413	        return {
   414	            status: PAYMENT_STATUS.BILLING_DISPUTE_PENDING,
   415	            isError: true,
